Read the integers at $A$, $B$, $C$ and $D$. Then mark $-6$ on the number line. The ticks are equally spaced.

[tikz]
\begin{tikzpicture}[x=0.3cm,y=0.6cm]
\draw[<->] (-21,0) -- (21,0);
\foreach \v in {-20,-18,...,20} {\draw (\v,0.13) -- (\v,-0.13);}
\foreach \v in {-20,-10,0,10,20} {\node[below] at (\v,-0.13) {$\v$};}
\foreach \v/\name in {-12/A,-4/B,6/C,15/D} {\draw[->] (\v,1.1) -- (\v,0.2); \node[above] at (\v,1.1) {$\name$};}
\end{tikzpicture}
[/tikz]

